26	// identitySpec 描述一条参与排序回归的序列：规范身份（指标名+完整标签集合）、
27	// 一个采样点与其数值。各序列时间戳互不相同，使点数与均值能一一对应到身份，
28	// 排序整理一旦串换统计值即可被查出。
29	type identitySpec struct {
30		name   string
31		labels map[string]string
32		ts     int64
33		value  float64
34	}
