36	// orderingSpecs 是期望的规范顺序（已按排序规则手工排好，并经实际比较器核对）。
37	// 同名 cpu 的序列刻意覆盖：无标签、数值外观的值（"10"/"2"）、长短键（"aa"/"b"）、
38	// 标签集合前缀、空字符串值、含逗号/等号/引号/反斜杠的键值、中文键值；
39	// 指标名再覆盖逗号与中文，验证名称按原始字符串字典序排在标签比较之前。
40	func orderingSpecs() []identitySpec {
41		return []identitySpec{
42			{name: "cpu", labels: map[string]string{}, ts: 100, value: 1}, // 无标签：同名最前
43			{name: "cpu", labels: map[string]string{"a": "10"}, ts: 101, value: 2},
44			{name: "cpu", labels: map[string]string{"a": "10", "b": "x"}, ts: 102, value: 3},
45			{name: "cpu", labels: map[string]string{"a": "2"}, ts: 103, value: 4}, // "10" < "2"
46			{name: "cpu", labels: map[string]string{"a": "2", "b": ""}, ts: 104, value: 5},
47			{name: "cpu", labels: map[string]string{"a": "2", "b": "1"}, ts: 105, value: 6},
48			{name: "cpu", labels: map[string]string{"a": `2,b="x"`}, ts: 106, value: 7},
49			{name: "cpu", labels: map[string]string{`a"b`: "1"}, ts: 107, value: 8},
50			{name: "cpu", labels: map[string]string{`a\b`: "1"}, ts: 108, value: 9},
51			{name: "cpu", labels: map[string]string{"aa": "1"}, ts: 109, value: 10}, // 键 "aa" < "b"
52			{name: "cpu", labels: map[string]string{"aa": "1", "b": ""}, ts: 110, value: 11},
53			{name: "cpu", labels: map[string]string{"aa": "1", "b": "1"}, ts: 111, value: 12},
54			{name: "cpu", labels: map[string]string{"b": "1"}, ts: 112, value: 13},
55			{name: "cpu", labels: map[string]string{"k": `"`}, ts: 113, value: 14},
56			{name: "cpu", labels: map[string]string{"k": ","}, ts: 114, value: 15},
57			{name: "cpu", labels: map[string]string{"k": "2"}, ts: 115, value: 16},
58			{name: "cpu", labels: map[string]string{"k": "中"}, ts: 116, value: 17},
59			{name: "cpu", labels: map[string]string{"k": "中", "z": "v"}, ts: 117, value: 18},
60			{name: "cpu", labels: map[string]string{"zone": "out"}, ts: 1018, value: 19},
61			{name: "cpu,total", labels: map[string]string{}, ts: 119, value: 20}, // 名称含逗号
62			{name: "指标", labels: map[string]string{"k": "v"}, ts: 120, value: 21},
63		}
64	}
