66	// identitySig 以 JSON 文本表示一条序列的规范身份（map 由 encoding/json 按键排序），
67	// 用于与结果中实际出现的身份逐一比对。
68	func identitySig(name string, labels map[string]string) string {
69		b, _ := json.Marshal(struct {
70			Name   string            `json:"name"`
71			Labels map[string]string `json:"labels"`
72		}{name, labels})
73		return string(b)
74	}
