100	// orderingBatch 把一组序列各取一个点编为一个写入批次。
101	func orderingBatch(specs []identitySpec) string {
102		parts := make([]string, len(specs))
103		for i, sp := range specs {
104			parts[i] = sample(sp.name, sp.ts, sp.value, sp.labels)
105		}
106		return "[" + strings.Join(parts, ",") + "]"
