109	// queryAll 构造省略 labels 的全序列查询 JSON 文本（labels 省略而非 null）。
110	func queryAll(name string, start, end int64) string {
111		return `{"op":"query","name":` + jsonString(name) +
112			fmt.Sprintf(`,"start":%d,"end":%d}`, start, end)
113	}
