200	// TestQueryKeepsSnapshotOrderAfterFiltering 是查询侧核心回归：子集标签与闭区间
201	// 过滤只删除不满足条件的条目，保留下来的条目仍是全量排序中的子序列，各自带着
202	// 完整标签、点数与均值；多出来的标签（如 k=中 之外的 z=v）不被裁剪，
203	// 空字符串值只匹配真实存在该标签的序列；全部被过滤时返回空数组。
204	func TestQueryKeepsSnapshotOrderAfterFiltering(t *testing.T) {
205		specs := orderingSpecs()
206		store := NewMetricStore()
207		mustOK(t, store, orderingBatch(permutedSpecs(specs, shuffledOrderingPerm)))
208	
209		// 追加若干第二点，使过滤后保留条目的 count/average 互不相同且非平凡：
210		//	{a:2}            再写 ts=300,value=10 → 与 ts=103 的 4 得 count=2,avg=7
211		//	{a:`2,b="x"`}    再写 ts=150,value=13 → 与 ts=106 的 7 得 count=2,avg=10
212		//	{zone:out}       再写 ts=5000,value=42（区间过滤时用于排除）
213		mustOK(t, store, "["+strings.Join([]string{
214			sample("cpu", 300, 10, map[string]string{"a": "2"}),
215			sample("cpu", 150, 13, map[string]string{"a": `2,b="x"`}),
216			sample("cpu", 5000, 42, map[string]string{"zone": "out"}),
217		}, ",")+"]")
218	
219		// 全量查询（[0,5000]）：19 条 cpu 的顺序与快照一致；点数/均值逐条核对，
220		// 含逗号/引号的身份不与其他序列串换统计值。默认每条一个点、值为其写入值，
221		// 仅三条追加过第二点的序列覆盖成 count=2 的实际统计。
222		full := mustQuery(t, store, queryLabels("cpu", 0, 5000, map[string]string{}))
223		if got, want := queryIdentitySigs(full), wantSigs(specs[:19]); !reflect.DeepEqual(got, want) {
224			t.Fatalf("full query order = %v\nwant %v", got, want)
225		}
226		wantStats := map[string]struct {
227			count int
228			avg   float64
229		}{}
230		for _, sp := range specs[:19] {
231			wantStats[identitySig(sp.name, sp.labels)] = struct {
232				count int
233				avg   float64
234			}{1, sp.value}
235		}
236		for sig, st := range map[string]struct {
237			count int
238			avg   float64
239		}{
240			identitySig("cpu", map[string]string{"a": "2"}):       {2, 7},
241			identitySig("cpu", map[string]string{"a": `2,b="x"`}): {2, 10},
242			identitySig("cpu", map[string]string{"zone": "out"}):  {2, 30.5},
243		} {
244			wantStats[sig] = st
245		}
246		for _, s := range full.Series {
247			sig := identitySig(s.Name, s.Labels)
248			want, ok := wantStats[sig]
249			if !ok {
250				t.Fatalf("unexpected series in full query: %s", sig)
251			}
252			if s.Count != want.count || s.Average != want.avg {
253				t.Fatalf("%s: count=%d average=%v, want %d/%v", sig, s.Count, s.Average, want.count, want.avg)
254			}
255			// 保留条目继续携带各自完整标签（map 与身份一致，未被子集条件裁剪）。
256			if !reflect.DeepEqual(s.Labels, labelOf(specs, sig)) {
257				t.Fatalf("%s labels = %v, want full label set", sig, s.Labels)
258			}
259		}
260	
261		// 子集 a=2 只命中真实值恰为 "2" 的三条（值文本为 `2,b="x"` 的序列不是 "2"，
262		// 不得被匹配）。它们在全量结果中的相对位置（specs[3..5]）原样保留，
263		// 双点序列在前、两个单点序列随后，count/avg 各自正确不串换。
264		sub := mustQuery(t, store, queryLabels("cpu", 0, 2000, map[string]string{"a": "2"}))
265		wantSub := []struct {
266			sig   string
267			count int
268			avg   float64
269		}{
270			{identitySig("cpu", map[string]string{"a": "2"}), 2, 7},
271			{identitySig("cpu", map[string]string{"a": "2", "b": ""}), 1, 5},
272			{identitySig("cpu", map[string]string{"a": "2", "b": "1"}), 1, 6},
273		}
274		if len(sub.Series) != len(wantSub) {
275			t.Fatalf("a=2 subset = %+v, want %d series", sub.Series, len(wantSub))
276		}
277		for i, w := range wantSub {
278			got := sub.Series[i]
279			if sig := identitySig(got.Name, got.Labels); sig != w.sig {
280				t.Fatalf("subset series[%d] = %s, want %s", i, sig, w.sig)
281			}
282			if got.Count != w.count || got.Average != w.avg {
283				t.Fatalf("%s stats = %d/%v, want %d/%v", w.sig, got.Count, got.Average, w.count, w.avg)
284			}
285		}
286		// 含逗号/引号的值按完整值精确命中其唯一序列（不是 a=2 的子集结果），
287		// 它带两个点、均值 10，统计值不与上面三条串换。
288		delim := queryOne(t, store, queryLabels("cpu", 0, 2000, map[string]string{"a": `2,b="x"`}))
289		if delim.Count != 2 || delim.Average != 10 {
290			t.Fatalf("exact delimiter-value series = %+v, want count=2 average=10", delim)
291		}
292	
293		// 空字符串值是真实标签：b="" 命中 {a:2,b:""} 与 {aa:1,b:""} 两条，
294		// 顺序沿用全量排序（specs[4] 在 specs[10] 前），且不会命中缺 b 的序列。
295		emptyVal := mustQuery(t, store, queryLabels("cpu", 0, 2000, map[string]string{"b": ""}))
296		if got := queryIdentitySigs(emptyVal); !reflect.DeepEqual(got, []string{
297			identitySig("cpu", map[string]string{"a": "2", "b": ""}),
298			identitySig("cpu", map[string]string{"aa": "1", "b": ""}),
299		}) {
300			t.Fatalf("b=\"\" subset order = %v", got)
301		}
302		if emptyVal.Series[0].Average != 5 || emptyVal.Series[1].Average != 11 {
303			t.Fatalf("b=\"\" averages = %v,%v, want 5 and 11", emptyVal.Series[0].Average, emptyVal.Series[1].Average)
304		}
305	
306		// 中文值与“额外标签”序列：k=中 命中两条，带 z=v 的一条排后（先比键 k 的值，
307		// 值相同才轮到下一对 z），且保留 z=v 这个子集之外的完整标签。
308		cn := mustQuery(t, store, queryLabels("cpu", 0, 2000, map[string]string{"k": "中"}))
309		if got := queryIdentitySigs(cn); !reflect.DeepEqual(got, []string{
310			identitySig("cpu", map[string]string{"k": "中"}),
311			identitySig("cpu", map[string]string{"k": "中", "z": "v"}),
312		}) {
313			t.Fatalf("k=中 subset order = %v", got)
314		}
315		if cn.Series[1].Labels["z"] != "v" || cn.Series[1].Count != 1 || cn.Series[1].Average != 18 {
316			t.Fatalf("extra-label series stats/labels = %+v", cn.Series[1])
317		}
318	
319		// 其他指标名精确匹配；名称中的逗号与中文按原名命中各自唯一序列。
320		if got := queryOne(t, store, queryAll("cpu,total", 0, 5000)); got.Count != 1 || got.Average != 20 {
321			t.Fatalf("cpu,total query = %+v", got)
322		}
323		if got := queryOne(t, store, queryLabels("指标", 0, 5000, map[string]string{"k": "v"})); got.Count != 1 || got.Average != 21 {
324			t.Fatalf("chinese-named query = %+v", got)
325		}
326	
327		// 只有区间外采样点的序列不出现：
328		//	[2001,4999] 内 a=2 四条都没有点 → 空数组；
329		//	k=中 两条的点都在 116/117，区间 [3001,4999] → 空数组；
330		//	zone=out 的第二点恰在 5000：[5000,5000] 闭区间命中一条 count=1,avg=42。
331		for _, line := range []string{
332			queryLabels("cpu", 2001, 4999, map[string]string{"a": "2"}),
333			queryLabels("cpu", 3001, 4999, map[string]string{"k": "中"}),
334		} {
335			if qr := mustQuery(t, store, line); len(qr.Series) != 0 {
336				t.Fatalf("%s = %+v, want empty series array", line, qr.Series)
337			}
338		}
339		atEnd := queryOne(t, store, queryLabels("cpu", 5000, 5000, map[string]string{"zone": "out"}))
340		if atEnd.Count != 1 || atEnd.Average != 42 {
341			t.Fatalf("closed-range endpoint query = %+v, want count=1 average=42", atEnd)
342		}
343	}
