func assertSeriesStats(t *testing.T, s QuerySeries, name string, labels map[string]string, count int, average float64, note string) {
	t.Helper()
	if s.Name != name {
		t.Fatalf("%s: name = %q, want %q", note, s.Name, name)
	}
