76		}
77	
78		// 行 3：start == end 只列出 3000 上的点。
79		m = decodeResultLine(t, lines[2])
80		points = m["series"].([]interface{})[0].(map[string]interface{})["points"].([]interface{})
81		if len(points) != 1 || points[0].(map[string]interface{})["value"].(float64) != 9 {
82			t.Fatalf("line 3 points = %v, want only (3000,9)", points)
83		}
84	
85		// 行 4：省略 labels 命中全部序列，host=a 在前、host=b 在后；
