package darksafe

import (
	"encoding/json"
	"math/big"
	"reflect"
	"strings"
	"testing"
)

// 本文件回归保障两种只读查询在相同条件下描述的是同一组采样：用户在同一份
// 已成功写入的数据上发送 op 为 "query" 的查询，再仅把 op 改成 "query_points"
// （指标名、标签条件、起止时间完全相同），两次结果必须逐序列对应——
// 同一组采样，统计数字能与明细逐条对应：
//
//   - 两种结果的序列身份（指标名+完整标签集合）与排列次序完全一致，
//     记录中的标签是该序列的完整标签集合，不能缩减成查询条件；
//   - 每条统计记录的 count 等于对应明细中的采样点数量；
//   - average 是明细中实际存储的 float64 值的算术平均：测试侧独立用 big.Rat
//     精确求和、精确除以点数后舍入到最近可表示 float64（正中取偶），
//     不调用生产代码的 ratToFloat64NearestEven，从而能拦住“统计遍历与
//     共享同一错误舍入实现的明细复核”这类双侧同源错误；
//   - 同名指标不同标签的序列分别统计，不能混在一起计算；
//  ́  - 只有闭区间 [start,end] 内的点参与某条记录 count/average；
//   - 条件未命中任何区间内采样时两种查询都成功返回非 nil 空数组，
//     不把没有点的序列补成 count=0、average=0 的记录。
//
// 失败信息一律指出是哪个查询区间、哪条序列（以指标名+完整标签签名）的明细或
// 统计不符合上述关系，便于定位后续修改造成的查询偏差。

// queryPair 是除 op 外完全相同的一对查询文本：用户复核时只切换 op，
// 其余条件（指标名、标签条件、起止时间）保持不变。
type queryPair struct {
	note   string  // 区间/场景的人类可读说明
	query  string  // op 为 "query"
	points string  // op 为 "query_points"
	start  int64   // 用于失败信息指明是哪个区间
	end    int64
}

// identityJSON 以规范 JSON 文本（encoding/json 对 map 按键排序）表示一条序列的
// 身份签名：指标名加完整标签集合。用于把两种结果中的序列逐一配对，并让失败信息
// 明确指出是哪条序列。
func identityJSON(name string, labels map[string]string) string {
	b, _ := json.Marshal(struct {
		Name   string            `json:"name"`
		Labels map[string]string `json:"labels"`
	}{name, labels})
	return string(b)
}

// detailMean 用与生产实现无关的方式从明细点切片复算算术平均：big.Rat 精确求和、
// 精确除以点数，再按二进制最近偶（round half to even）舍入为 float64。
// 它模拟产品约定（精确有理数平均 → 最近可表示值、正中取偶），但独立实现，
// 不调用 ratToFloat64DetailMean 生产函数，避免统计侧与复核侧同源出错时漏检。
func detailMean(t *testing.T, points []Point) float64 {
	t.Helper()
	if len(points) == 0 {
		t.Fatalf("internal: detailMean called with no points")
	}
	sum := new(big.Rat)
	r := new(big.Rat)
	for _, p := range points {
		sum.Add(sum, r.SetFloat64(p.Value))
	}
	sum.Quo(sum, big.NewRat(int64(len(points)), 1))
	return ratNearestEvenIndep(t, sum)
}

// ratNearestEvenIndep 是 detailMean 的独立最近偶舍入实现：把精确平均按
// 2^-1074（float64 最小分度）量化，余数过半进位、不足舍去、正中时末位取偶，
// 随后用 math.Frexp/Ldexp 组装回 float64。与生产代码路径完全分开。
func ratNearestEvenIndep(t *testing.T, x *big.Rat) float64 {
	t.Helper()
	if x.Sign() == 0 {
		return 0
	}
	a := new(big.Rat).Set(x)
	neg := false
	if a.Sign() < 0 {
		neg = true
		a.Neg(a)
	}
	// 在 2^-1074 分度上量化：n 与余数 frac 满足 a = (n + frac) · 2^-1074，
	// 0 <= frac < 1；然后对 frac 做最近偶判定。
	step := new(big.Rat).SetFrac(big.NewInt(1), new(big.Int).Lsh(big.NewInt(1), 1074))
	q := new(big.Rat).Quo(a, step)
	n, r2 := new(big.Int).QuoRem(q.Num(), q.Denom(), new(big.Int))
	cmp := new(big.Int).Lsh(r2, 1).Cmp(q.Denom()) // 2*frac 与 1 比较
	if cmp > 0 || (cmp == 0 && n.Bit(0) == 1) {
		n.Add(n, big.NewInt(1))
	}
	// n · 2^-1074 组装为 float64：正规数区间内 Ldexp 的运行时舍入不会发生
	// （n 的规模保证目标值本身可表示，或仅在极大值边界才需要处理进位）。
	f := ldexpFromMantissa(t, n)
	if neg {
		return -f
	}
	return f
}

// ldexpFromMantissa 把整数尾数 n（n · 2^-1074）组装为非负 float64。
// 若量化后的 n 达到 2^2047 或更大（只可能发生在输入均值接近溢出边界时，
// 本回归的数据都远离该边界），直接 t.Fatal 提示，避免静默使用未验证路径。
func ldexpFromMantissa(t *testing.T, n *big.Int) float64 {
	t.Helper()
	if n.Sign() == 0 {
		return 0
	}
	if n.BitLen() > 2047 {
		t.Fatalf("internal: independent mean rounding does not handle overflow-near mantissa %v", n)
	}
	// 找到最高位 b：n = m · 2^k，m 为奇数或允许保留全部位；直接以 n 为尾数、
	// 指数 -1074 调用 Ldexp，float64 转换 n 时若丢失低位说明 n 超过 2^53——
	// 但最近偶量化后若结果可表示，去掉 trailing zero 后有效位不超过 53 位。
	k := uint(0)
	m := new(big.Int).Set(n)
	for m.Bit(0) == 0 {
		m.Rsh(m, 1)
		k++
	}
	if m.BitLen() > 53 {
		t.Fatalf("internal: rounded mean not exactly representable, mantissa %v bits %d", m, m.BitLen())
	}
	return mathLdexp(float64(m.Int64()), int(k)-1074)
}

// assertQueryPairCorrespond 对同一区间执行两次查询（仅 op 不同），断言：
//   - 双方都成功，status/op 正确；
//   - 序列身份（name+完整标签）与排列次序逐一相同；
//   - 每条序列：统计 count == 明细点数，average == 从明细独立复算的精确平均
//     （最近偶 float64）；
//   - 明细点按时间戳严格升序、时间戳两两不同；
//   - 每个明细点都落在闭区间 [start,end] 内；
//   - 统计侧不出现明细侧没有的序列，反之亦然；
//   - 空结果是成功的非 nil 空数组。
//
// 每个失败信息都带区间与序列身份签名，明确指出是哪条序列的明细或统计不符。
func assertQueryPairCorrespond(t *testing.T, store *MetricStore, p queryPair) {
	t.Helper()
	stats := mustQuery(t, store, p.query)
	detail := mustQueryPoints(t, store, p.points)
	if stats.Status != "ok" || stats.Op != "query" {
		t.Fatalf("[%d,%d] %s: stats envelope = %q/%q, want ok/query",
			p.start, p.end, p.note, stats.Status, stats.Op)
	}
	if detail.Status != "ok" || detail.Op != "query_points" {
		t.Fatalf("[%d,%d] %s: detail envelope = %q/%q, want ok/query_points",
			p.start, p.end, p.note, detail.Status, detail.Op)
	}

	// 身份与排列次序逐一相同。
	if len(stats.Series) != len(detail.Series) {
		t.Fatalf("[%d,%d] %s: query returned %d series but query_points returned %d:\nstats:  %s\ndetail: %s",
			p.start, p.end, p.note, len(stats.Series), len(detail.Series),
			seriesSigsStats(stats.Series), seriesSigsDetail(detail.Series))
	}
	for i := range stats.Series {
		qs := stats.Series[i]
		ds := detail.Series[i]
		sigSt := identityJSON(qs.Name, qs.Labels)
		sigDe := identityJSON(ds.Name, ds.Labels)
		if sigSt != sigDe {
			t.Fatalf("[%d,%d] %s: series[%d] identity mismatch:\nquery       #%d = %s\nquery_points #%d = %s",
				p.start, p.end, p.note, i, i, sigSt, i, sigDe)
		}
	}

	// 逐条核对 count/average 与明细的对应关系。
	for i := range stats.Series {
		qs := stats.Series[0 : i+1][i] // keep refs simple
		_ = qs
		stat := stats.Series[i]
		det := detail.Series[i]
		sig := identityJSON(stat.Name, stat.Labels)

		// 记录中的标签必须是完整标签集合：检查每个点所属序列的完整标签是否
		// 就是返回的标签（数据写入时 setup 预期 map 已在各场景中单独核对，
		// 这里锁定两种结果都不能把标签缩减成查询条件）。
		if !sameLabels(stat.Labels, det.Labels) {
			t.Fatalf("[%d,%d] %s: %s: labels differ between results: stats=%v detail=%v",
				p.start, p.end, p.note, sig, stat.Labels, det.Labels)
		}

		// count == 明细点数。
		if stat.Count != len(det.Points) {
			t.Fatalf("[%d,%d] %s: %s: count=%d but detail lists %d points: %+v",
				p.start, p.end, p.note, sig, stat.Count, len(det.Points), det.Points)
		}

		// 空点记录不应存在：没有点的序列不能补成 count=0 条目（runQuery 与
		// runQueryPoints 都跳过 count==0；这里确保双侧都没漏）。
		if len(det.Points) == 0 {
			t.Fatalf("[%d,%d] %s: %s: zero-point entry must not be emitted by either query",
				p.start, p.end, p.note, sig)
		}

		// 明细按时间戳严格升序且全部在闭区间内；值是实际存储的有限 float64。
		for j, pt := range det.Points {
			if pt.Timestamp < p.start || pt.Timestamp > p.end {
				t.Fatalf("[%d,%d] %s: %s: detail point[%d] ts=%d is outside the closed range",
					p.start, p.end, p.note, sig, j, pt.Timestamp)
			}
			if j > 0 && det.Points[j-1].Timestamp >= pt.Timestamp {
				t.Fatalf("[%d,%d] %s: %s: detail not strictly ascending at %d: %+v",
					p.start, p.end, p.note, sig, j, det.Points)
            }
		}

		// average == 从明细独立复算的结果（big.Rat 精确平均 → 最近偶 float64）。
		wantAvg := detailMean(t, det.Points)
		if stat.Average != wantAvg {
			t.Fatalf("[%d,%d] %s: %s: average=%v but recomputed from detail = %v (count=%d, detail=%+v)",
				p.start, p.end, p.note, sig, stat.Average, wantAvg, len(det.Points), det.Points)
		}
	}
}

// seriesSigsStats / seriesSigsDetail 在失败信息中列出两侧全部序列身份。
func seriesSigsStats(xs []QuerySeries) string {
	parts := make([]string, len(xs))
	for i, x := range xs {
		parts[i] = identityJSON(x.Name, x.Labels)
	}
	return "[" + strings.Join(parts, ", ") + "]"
}

func seriesSigsDetail(xs []QueryPointsSeries) string {
	parts := make([]string, len(xs))
	for i, x := range xs {
		parts[i] = identityJSON(x.Name, x.Labels)
	}
	return "[" + strings.Join(parts, ", ") + "]"
}

// pairsFor 用同一组条件构造仅 op 不同的一对查询文本（labels 为 nil 时省略
// labels 字段；非 nil 时按子集匹配，即使是空 map）。
func pairsFor(name string, start, end int64, labels map[string]string) queryPair {
	if labels == nil {
		return queryPair{
			note:   "omit labels",
			query:  queryAll(name, start, end),
			points: queryPointsAll(name, start, end),
			start:  start,
			end:    end,
		}
	}
	return queryPair{
		note:   "labels " + jsonLabels(labels),
		query:  queryLabels(name, start, end, labels),
		points: queryPointsLabels(name, start, end, labels),
		start:  start,
		end:    end,
	}
}

// TestQueryAndPointsDescribeSameSamplesCancellation 是任务书指定的核心采样：
// 同一序列在 1000、2000、3000 分别存入 1e16、1、-1e16。包含三个点的区间内
// 明细按时间升序保留这三个存储值，统计 count=3、average=0.3333333333333333；
// 正负大数抵消不能吞掉中间的 1。区间外的点与同名但标签不同的另一条序列都
// 不改变这条记录。
func TestQueryAndPointsDescribeSameSamplesCancellation(t *testing.T) {
	store := NewMetricStore()
	labelsA := map[string]string{"host": "a"}
	mustOK(t, store, "["+
		sample("cpu", 500, 77, labelsA)+","+ // 区间下方之外
		sample("cpu", 1000, 1e16, labelsA)+","+
		sample("cpu", 2000, 1, labelsA)+","+
		sample("cpu", 3000, -1e16, labelsA)+","+
		sample("cpu", 4000, 88, labelsA)+","+ // 区间上方之外
		// 同名但标签不同的另一条序列，值刻意取成若被混入就会改变 host=a 的均值。
		sample("cpu", 2000, 999999, map[string]string{"host": "b"})+"]")

	pair := pairsFor("cpu", 1000, 3000, labelsA)
	stats := mustQuery(t, store, pair.query)
	detail := mustQueryPoints(t, store, pair.points)

	// 明细侧：恰好一条 host=a 序列，三个点按时间升序，值是实际存储的 float64。
	if len(detail.Series) != 1 {
		t.Fatalf("[1000,3000] host=a: detail series = %s, want exactly 1 (host=b must be excluded)",
			seriesSigsDetail(detail.Series))
	}
	wantPoints := []Point{
		{Timestamp: 1000, Value: 1e16},
		{Timestamp: 2000, Value: 1},
		{Timestamp: 3000, Value: -1e16},
	}
	if !reflect.DeepEqual(detail.Series[0].Points, wantPoints) {
		t.Fatalf("[1000,3000] %s: detail points = %+v, want ascending %+v",
			identityJSON("cpu", labelsA), detail.Series[0].Points, wantPoints)
	}
	// 统计侧：一条 host=a 记录，count=3，average 是 1/3 的最近 float64。
	if len(stats.Series) != 1 {
		t.Fatalf("[1000,3000] host=a: stats series = %s, want exactly 1", seriesSigsStats(stats.Series))
	}
	s0 := stats.Series[0]
	if s0.Count != 3 {
		t.Fatalf("[1000,3000] %s: count = %d, want 3", identityJSON("cpu", labelsA), s0.Count)
	}
	if s0.Average != 1.0/3.0 {
		t.Fatalf("[1000,3000] %s: average = %v, want %v (1/3 nearest float64)",
			identityJSON("cpu", labelsA), s0.Average, 1.0/3.0)
	}
	b, _ := json.Marshal(s0.Average)
	if string(b) != "0.3333333333333333" {
		t.Fatalf("[1000,3000] %s: average JSON = %s, want 0.3333333333333333",
			identityJSON("cpu", labelsA), b)
	}
	// 标签是完整集合而非查询条件（此处单标签天然相等，但仍锁定 labels 身份字段存在且完整）。
	if !sameLabels(s0.Labels, labelsA) {
		t.Fatalf("[1000,3000] %s: labels = %v, want full set %v",
			identityJSON("cpu", labelsA), s0.Labels, labelsA)
	}

	// 通用对应关系校验（身份/次序、count==len(points)、独立复算平均、点在区间内且升序）。
	assertQueryPairCorrespond(t, store, pair)

	// 同名不同标签序列分别统计：host=b 在同区间有自己的 count=1、average=999999，
	// 两个序列同时返回时也不能把值混在一起。
	both := pairsFor("cpu", 1000, 3000, nil)
	statsAll := mustQuery(t, store, both.query)
	detailAll := mustQueryPoints(t, store, both.points)
	if len(statsAll.Series) != 2 || len(detailAll.Series) != 2 {
		t.Fatalf("[1000,3000] all-labels: series count stats=%d detail=%d, want 2",
			len(statsAll.Series), len(detailAll.Series))
	}
	assertQueryPairCorrespond(t, store, both)
	// host=a 与 host=b 的统计必须分别正确：host=a 仍为 3 点均值 1/3；host=b 单点 999999。
	qa := statsAll.Series[findQueryIndex(t, statsAll, "cpu", labelsA)]
	qb := statsAll.Series[findQueryIndex(t, statsAll, "cpu", map[string]string{"host": "b"})]
	if qa.Count != 3 || qa.Average != 1.0/3.0 {
		t.Fatalf("host=a mixed in with host=b? stats = %+v, want count=3 average=1/3", qa)
	}
	if qb.Count != 1 || qb.Average != 999999 {
		t.Fatalf("host=b stats = %+v, want count=1 average=999999", qb)
	}
	da := detailAll.Series[findPointsIndex(t, detailAll, "cpu", labelsA)]
	db := detailAll.Series[findPointsIndex(t, detailAll, "cpu", map[string]string{"host": "b"})]
	// 区间外的 500/4000 两个 host=a 点仍不得出现在明细中。
	if len(da.Points) != 3 {
		t.Fatalf("host=a detail should have 3 in-range points, got %+v", da.Points)
	}
	if !reflect.DeepEqual(db.Points, []Point{{Timestamp: 2000, Value: 999999}}) {
		t.Fatalf("host=b detail = %+v, want single point (2000,999999)", db.Points)
	}
}

// TestQueryAndPointsSingleTimestampRange 区间端点语义：闭区间包含两个端点；
// start == end 且该位置有点时，明细只列那个点，统计 count=1、均值等于该点的
// 实际存储值。区间只命中序列部分点时，统计只基于命中的子集。
func TestQueryAndPointsSingleTimestampRange(t *testing.T) {
	store := NewMetricStore()
	labels := map[string]string{"host": "a"}
	mustOK(t, store, "["+
		sample("cpu", 1000, 2, labels)+","+
		sample("cpu", 2000, 4, labels)+","+
		sample("cpu", 3000, 9, labels)+"]")

	// start == end，逐位置核对 count==1 与 average==存储值本身。
	for _, want := range []Point{
		{Timestamp: 1000, Value: 2},
		{Timestamp: 2000, Value: 4},
		{Timestamp: 3000, Value: 9},
	} {
		pair := pairsFor("cpu", want.Timestamp, want.Timestamp, labels)
		detail := mustQueryPoints(t, store, pair.points)
		if len(detail.Series) != 1 || !reflect.DeepEqual(detail.Series[0].Points, []Point{want}) {
			t.Fatalf("[%d,%d] detail = %+v, want single point %+v",
				want.Timestamp, want.Timestamp, detail.Series, want)
		}
		assertQueryPairCorrespond(t, store, pair)
		stats := mustQuery(t, store, pair.query)
		if stats.Series[0].Count != 1 || stats.Series[0].Average != want.Value {
			t.Fatalf("[%d,%d] stats = %+v, want count=1 average=%v",
				want.Timestamp, want.Timestamp, stats.Series[0], want.Value)
		}
	}

	// 闭区间两个端点都包含：[1000,2000] 两个点，[1000,3000] 三个点。
	assertQueryPairCorrespond(t, store, pairsFor("cpu", 1000, 2000, labels))
	assertQueryPairCorrespond(t, store, pairsFor("cpu", 1000, 3000, labels))
	// 部分区间 [1500,2500] 只命中中间一个点。
	assertQueryPairCorrespond(t, store, pairsFor("cpu", 1500, 2500, labels))
}

// TestQueryAndPointsSubsetMatchPreservesExtraLabels 按标签子集查询命中多条
// 序列时，两种结果的序列身份/次序一致，各条明细与统计分别对应，额外标签
// 也在两种结果中完整保留（不缩减成查询条件）。
func TestQueryAndPointsSubsetMatchPreservesExtraLabels(t *testing.T) {
	store := NewMetricStore()
	mustOK(t, store, `[
		{"name":"m","timestamp":10,"value":100,"labels":{"zone":"x"}},
		{"name":"m","timestamp":20,"value":200,"labels":{"zone":"x","host":"h"}},
		{"name":"m","timestamp":30,"value":300,"labels":{"zone":"x","host":"h2"}},
		{"name":"m","timestamp":40,"value":400,"labels":{"zone":"y"}},
		{"name":"m","timestamp":10,"value":500}
	]`)

	// 子集 zone=x 命中三条序列；查询条件只有一个标签，返回必须完整保留额外标签。
	pair := pairsFor("m", 0, 1000, map[string]string{"zone": "x"})
	assertQueryPairCorrespond(t, store, pair)
	stats := mustQuery(t, store, pair.query)
	detail := mustQueryPoints(t, store, pair.points)
	wantFullLabels := []map[string]string{
		{"zone": "x", "host": "h"},  // 双标签在前（host < zone）
		{"zone": "x", "host": "h2"}, //
		{"zone": "x"},               // 单标签最后
	}
	if len(stats.Series) != 3 || len(detail.Series) != 3 {
		t.Fatalf("zone=x subset stats=%d detail=%d, want 3 series",
			len(stats.Series), len(detail.Series))
	}
	for i, want := range wantFullLabels {
		if !sameLabels(stats.Series[i].Labels, want) {
			t.Fatalf("zone=x series[%d] stats labels = %v, want full set %v",
				i, stats.Series[i].Labels, want)
		}
		if !sameLabels(detail.Series[i].Labels, want) {
			t.Fatalf("zone=x series[%d] detail labels = %v, want full set %v",
				i, detail.Series[i].Labels, want)
		}
	}
	// 双标签序列的明细与统计分别对应：host=h 的点在 20，值 200；host=h2 在 30，值 300。
	if !reflect.DeepEqual(detail.Series[0].Points, []Point{{Timestamp: 20, Value: 200}}) {
		t.Fatalf("host=h detail = %+v, want (20,200)", detail.Series[0].Points)
	}
	if !reflect.DeepEqual(detail.Series[1].Points, []Point{{Timestamp: 30, Value: 300}}) {
		t.Fatalf("host=h2 detail = %+v, want (30,300)", detail.Series[1].Points)
	}

	// 进一步限定到唯一带额外标签的序列：身份、count、average、额外标签都对。
	one := pairsFor("m", 0, 1000, map[string]string{"zone": "x", "host": "h"})
	assertQueryPairCorrespond(t, store, one)
	st := mustQuery(t, store, one.query)
	if !sameLabels(st.Series[0].Labels, map[string]string{"zone": "x", "host": "h"}) ||
		st.Series[0].Count != 1 || st.Series[0].Average != 200 {
		t.Fatalf("fully-specified subset = %+v, want {host:h,zone:x} count=1 avg=200", st.Series[0])
	}

	// 区间只命中部分序列：[15,25] 内只有 host=h(20,200) 与无额外标签的
	// zone=x(没有该区间内点？zone=x 单点在 ts=10，不在) —— 这里 [15,25]
	// 只命中 host=h 一条；zone=x(单标签,ts=10) 与 host=h2(ts=30) 不出现。
	partial := pairsFor("m", 15, 25, map[string]string{"zone": "x"})
	assertQueryPairCorrespond(t, store, partial)
	ps := mustQuery(t, store, partial.query)
	if len(ps.Series) != 1 || !sameLabels(ps.Series[0].Labels, map[string]string{"zone": "x", "host": "h"}) {
		t.Fatalf("[15,25] zone=x = %+v, want only host=h series", ps.Series)
	}
}

// TestQueryAndPointsNoMatchBothEmpty 条件未命中任何区间内采样时，两种查询都
// 成功返回空 series 数组（非 nil，序列化为 []），不补零点数零均值记录——
// 包括指标不存在、标签条件无命中、区间内无点（序列在区间外有点）三种情形，
// 以及省略 labels 与显式 {} 两种写法。
func TestQueryAndPointsNoMatchBothEmpty(t *testing.T) {
	store := NewMetricStore()
	mustOK(t, store, `[
		{"name":"cpu","timestamp":1000,"value":2,"labels":{"host":"a"}},
		{"name":"cpu","timestamp":2000,"value":4,"labels":{"host":"a"}},
		{"name":"cpu","timestamp":2000,"value":5,"labels":{"host":"b"}}
	]`)

	cases := []queryPair{}
	// 指标不存在。
	cases = append(cases, pairsFor("nope", 0, 5000, nil))
	cases = append(cases, pairsFor("nope", 0, 5000, map[string]string{}))
	// 标签条件无命中：值不匹配 / 缺少该标签键。
	cases = append(cases, pairsFor("cpu", 0, 5000, map[string]string{"host": "zzz"}))
	cases = append(cases, pairsFor("cpu", 0, 5000, map[string]string{"zone": "x"}))
	// 区间内没有点（命中序列的点都在区间外）。
	cases = append(cases, pairsFor("cpu", 1001, 1999, nil))
	cases = append(cases, pairsFor("cpu", 2001, 9000, map[string]string{"host": "a"}))
	// 标签命中但区间无点：host=b 的点在 2000，查 host=b 的空区间。
	cases = append(cases, pairsFor("cpu", 1000, 1000, map[string]string{"host": "b"}))
	// start == end 落在没有点的位置（同指标下多条序列在该时刻都无采样）。
	cases = append(cases, pairsFor("cpu", 1500, 1500, nil))

	for _, p := range cases {
		t.Run(p.note+" "+fmtRange(p), func(t *testing.T) {
			assertQueryPairCorrespond(t, store, p)
			stats := mustQuery(t, store, p.query)
			detail := mustQueryPoints(t, store, p.points)
			if stats.Series == nil || len(stats.Series) != 0 {
				t.Fatalf("%s [%d,%d]: stats series = %+v, want non-nil empty",
					p.note, p.start, p.end, stats.Series)
			}
			if detail.Series == nil || len(detail.Series) != 0 {
				t.Fatalf("%s [%d,%d]: detail series = %+v, want non-nil empty",
					p.note, p.start, p.end, detail.Series)
			}
			if raw := marshalCompact(t, stats); raw != `{"status":"ok","op":"query","series":[]}` {
				t.Fatalf("%s [%d,%d]: stats JSON = %s, want empty series []", p.note, p.start, p.end, raw)
			}
			if raw := marshalCompact(t, detail); raw != `{"status":"ok","op":"query_points","series":[]}` {
				t.Fatalf("%s [%d,%d]: detail JSON = %s, want empty series []", p.note, p.start, p.end, raw)
			}
		})
	}
}

// fmtRange 用 "[start,end]" 描述区间，用于子测试名。
func fmtRange(p queryPair) string {
	return "[" + itoa(p.start) + "," + itoa(p.end) + "]"
}

// itoa 不引入 strconv 到本文件的命名冲突（保持与现有测试一致的最小依赖）。
func itoa(v int64) string {
	if v == 0 {
		return "0"
	}
	neg := v < 0
	if neg {
		v = -v
	}
	var b [32]byte
	i := len(b)
	for v > 0 {
		i--
		b[i] = byte('0' + v%10)
		v /= 10
	}
	if neg {
		i--
		b[i] = '-'
	}
	return string(b[i:])
}

// TestQueryAndPointsMultiSeriesRangesTable 用表格驱动覆盖多种区间：每条区间
// 两种查询逐序列对应，统计都能从该区间的明细独立复算出来；不同标签序列、
// 区间外点都不串。这张表专门设计成统计值非平凡（每条命中序列在不同区间
// 内 count 与 average 都不同），能区分“区间过滤错”与“序列混算错”。
func TestQueryAndPointsMultiSeriesRangesTable(t *testing.T) {
	store := NewMetricStore()
	// 三条同名不同标签序列 + 一个不同名指标。时间戳部分重叠，区分序列混算与
	// 区间过滤两种错误。
	mustOK(t, store, "["+
		sample("m", 10, 2, map[string]string{"host": "a"})+","+
		sample("m", 20, 4, map[string]string{"host": "a"})+","+
		sample("m", 30, 6, map[string]string{"host": "a"})+","+
		sample("m", 40, 8, map[string]string{"host": "a"})+","+
		sample("m", 10, 20, map[string]string{"host": "b"})+","+
		sample("m", 20, 40, map[string]string{"host": "b"})+","+
		sample("m", 30, 60, map[string]string{"host": "b"})+","+
		sample("m", 25, 7, map[string]string{"host": "c", "dc": "1"})+","+ // 带额外标签
		sample("other", 20, 999, nil)+"]")

	type tc struct {
		name   string
		start  int64
		end    int64
		labels map[string]string // nil = 省略 labels
	}
	cases := []tc{
		{"all labels full range", 0, 100, nil},
		{"all labels [20,30]", 20, 30, nil},
		{"all labels single ts 20", 20, 20, nil},
		{"all labels single ts 25", 25, 25, nil},
		{"host=a full", 0, 100, map[string]string{"host": "a"}},
		{"host=a [15,35]", 15, 35, map[string]string{"host": "a"}},
		{"host=a [30,40]", 30, 40, map[string]string{"host": "a"}},
		{"host=b [10,20]", 10, 20, map[string]string{"host": "b"}},
		{"host=b [25,100]", 25, 100, map[string]string{"host": "b"}},
		{"host=b empty interior", 11, 19, map[string]string{"host": "b"}},
		{"host=c extra labels", 0, 100, map[string]string{"host": "c"}},
		{"host=c subset dc", 0, 100, map[string]string{"host": "c", "dc": "1"}},
		{"host=c wrong extra", 0, 100, map[string]string{"host": "c", "dc": "2"}},
		{"other metric by name", 0, 100, nil},
		{"unknown metric", 0, 100, map[string]string{}},
	}
	for _, c := range cases {
		t.Run(c.name,
			// 对 other/unknown 用各自名字构造 pair。
			runPair := func(t *testing.T) {
				name := "m"
				if strings.Contains(c.name, "other metric") || strings.Contains(c.name, "unknown metric") {
					if strings.Contains(c.name, "other metric") {
						name = "other"
					} else {
						name = "nope"
					}
				}
				pair := pairsFor(name, c.start, c.end, c.labels)
				assertQueryPairCorrespond(t, store, pair)
			})
		_ = func() {}()
	}
	// 上面的 t.Run 写法在 Go 中不能直接把闭包当 body；改为显式循环体：
	for _, c := range cases {
		name := "m"
		if strings.Contains(c.name, "other metric") {
			name = "other"
		}
		if strings.Contains(c.name, "unknown metric") {
			name = "nope"
		}
		pair := pairsFor(name, c.start, c.end, c.labels)
		t.Run(c.name, func(t *testing.T) {
			assertQueryPairCorrespond(t, store, pair)
		})
	}
}

// TestQueryAndPointsIndependentRecomputationCatchesWrongRounding 保障独立复算
// 能拦住错误的舍入/求和：构造精确平均不是 float64 朴素求和结果的数据
// （1e16、1、-1e16 已在核心用例覆盖，这里再补一组：总和超过 float64
// 有限范围时均值仍必须从明细得到有限且正确的结果）。
func TestQueryAndPointsIndependentRecomputationCatchesWrongRounding(t *testing.T) {
	store := NewMetricStore()
	mustOK(t, store, `[
		{"name":"m","timestamp":1,"value":1e308},
		{"name":"m","timestamp":2,"value":1e308},
		{"name":"m","timestamp":3,"value":1e308}
	]`)
	pair := pairsFor("m", 0, 100, nil)
	assertQueryPairCorrespond(t, store, pair)
	stats := mustQuery(t, store, pair.query)
	if stats.Series[0].Count != 3 || stats.Series[0].Average != 1e308 {
		t.Fatalf("overflow-range mean = %+v, want count=3 average=1e308", stats.Series[0])
	}

	// 再验证一组需要最近偶判定的两个相邻 float64：明细复算与生产侧都必须选偶数。
	store2 := NewMetricStore()
	mustOK(t, store2, `[
		{"name":"m","timestamp":1,"value":1},
		{"name":"m","timestamp":2,"value":1.0000000000000002}
	]`)
	pair2 := pairsFor("m", 1, 2, nil)
	assertQueryPairCorrespond(t, store2, pair2)
	s := mustQuery(t, store2, pair2.query).Series[0]
	if s.Count != 2 || s.Average != 1 {
		t.Fatalf("tie-to-even = %+v, want count=2 average=1", s)
	}
}

