			continue
		}
		sum.Quo(sum, r.SetInt64(int64(count)))
		out = append(out, QuerySeries{
			Name:   entry.ref.Name,
			Labels: entry.ref.Labels,
			Count:  count,
			// 精确平均舍入到最近可表示 float64（正中取偶）；精确为零时返回 +0。
			Average: ratToFloat64NearestEven(sum),
		})"""
